import ast
import operator

class SafeMathEvaluator(ast.NodeVisitor):
    """Custom NodeVisitor that safely evaluates mathematical expression trees.

    Strictly whitelists allowed arithmetic nodes and blocks all other syntax.
    """
    # Allowed binary operators mapping
    BIN_OPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    # Allowed unary operators mapping
    UNARY_OPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def evaluate(self, node: ast.AST):
        return self.visit(node)

    def visit_Expression(self, node: ast.Expression):
        return self.visit(node.body)

    def visit_Constant(self, node: ast.Constant):
        if not isinstance(node.value, (int, float)):
            raise TypeError(f"Unsupported constant type: {type(node.value).__name__}")
        return node.value

    def visit_BinOp(self, node: ast.BinOp):
        op_type = type(node.op)
        if op_type not in self.BIN_OPS:
            raise TypeError(f"Unsupported binary operator: {op_type.__name__}")

        left_val = self.visit(node.left)
        right_val = self.visit(node.right)

        return self.BIN_OPS[op_type](left_val, right_val)

    def visit_UnaryOp(self, node: ast.UnaryOp):
        op_type = type(node.op)
        if op_type not in self.UNARY_OPS:
            raise TypeError(f"Unsupported unary operator: {op_type.__name__}")

        operand_val = self.visit(node.operand)
        return self.UNARY_OPS[op_type](operand_val)

    def generic_visit(self, node: ast.AST):
        """Block any syntax nodes that are not explicitly whitelisted."""
        raise ValueError(f"Forbidden syntax node: {type(node).__name__}")

