/* CSS Design System and Visual Identity for Basic Web Calculator */

:root {
  /* Default: Light Mode Tokens (from DESIGN.md) */
  --bg-app: #F8F9FA;
  --bg-frame: #F1F3F4;
  --bg-display: #E8EAED;
  --text-primary: #202124;
  --text-result-preview: #5F6368;
  --text-result-final: #1A73E8;
  --text-error: #EA4335;
  --btn-operand-bg: #FFFFFF;
  --btn-operand-text: #3C4043;
  --btn-operator-bg: #F1F3F4;
  --btn-operator-text: #1A73E8;
  --btn-command-bg: #DADCE0;
  --btn-command-text: #3C4043;
  --btn-equals-bg: #1A73E8;
  --btn-equals-text: #FFFFFF;
  --btn-focus-ring: #1A73E8;
  --border-btn: 1px solid rgba(0, 0, 0, 0.08);
  --shadow-btn: 0px 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-btn-hover: 0px 1px 3px rgba(0, 0, 0, 0.1);
  --display-inset-shadow: inset 0px 2px 4px rgba(0, 0, 0, 0.08);
}

@media (prefers-color-scheme: dark) {
  :root {
    /* Dark Mode Tokens (from DESIGN.md) */
    --bg-app: #202124;
    --bg-frame: #303134;
    --bg-display: #202124;
    --text-primary: #E8EAED;
    --text-result-preview: #9AA0A6;
    --text-result-final: #8AB4F8;
    --text-error: #F28B82;
    --btn-operand-bg: #3C4043;
    --btn-operand-text: #E8EAED;
    --btn-operator-bg: #303134;
    --btn-operator-text: #8AB4F8;
    --btn-command-bg: #4A4D51;
    --btn-command-text: #E8EAED;
    --btn-equals-bg: #8AB4F8;
    --btn-equals-text: #202124;
    --btn-focus-ring: #8AB4F8;
    --border-btn: 1px solid rgba(255, 255, 255, 0.05);
    --shadow-btn: 0px 1px 2px rgba(0, 0, 0, 0.15);
    --shadow-btn-hover: 0px 2px 4px rgba(0, 0, 0, 0.2);
    --display-inset-shadow: inset 0px 2px 4px rgba(0, 0, 0, 0.25);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
}

body {
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  background-color: var(--bg-app);
  color: var(--text-primary);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  transition: background-color 0.3s ease-in-out, color 0.3s ease-in-out;
}

/* Outer layout frame */
.calculator-container {
  width: 100%;
  max-width: 400px;
  background-color: var(--bg-frame);
  border-radius: 16px; /* frame corner radius */
  padding: 24px; /* padding-outer */
  box-shadow: 0px 8px 32px rgba(0, 0, 0, 0.15);
  border: 1px solid rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
  outline: none;
  transition: background-color 0.3s ease-in-out;
}

/* Recessed display panel card bezel */
.display-panel {
  background-color: var(--bg-display);
  border-radius: 12px; /* rounded-display */
  padding: 16px; /* padding-inner */
  box-shadow: var(--display-inset-shadow);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  min-height: 120px;
  margin-bottom: 20px; /* display-to-grid */
  text-align: right;
  overflow: hidden;
  transition: background-color 0.3s ease-in-out;
}

/* Stable monospace display numbers formatting */
.display-monospace {
  font-family: "Courier New", "Menlo", "SF Mono", "Consolas", monospace;
  overflow-x: auto;
  white-space: nowrap;
  width: 100%;
  scrollbar-width: none; /* Hide scrollbars */
}

.display-monospace::-webkit-scrollbar {
  display: none;
}

.display-history {
  font-size: 14px; /* size-history */
  color: var(--text-result-preview);
  min-height: 20px;
  margin-bottom: 4px;
}

.display-input {
  font-size: 28px; /* size-display-input */
  color: var(--text-primary);
  font-weight: 500;
  min-height: 36px;
  margin-bottom: 4px;
}

.display-result {
  font-size: 40px; /* size-display-result */
  font-weight: 700;
  min-height: 48px;
  transition: color 0.15s ease-in-out;
}

.display-result.preview {
  color: var(--text-result-preview);
  opacity: 0.7;
}

.display-result.final {
  color: var(--text-result-final);
}

.display-result.error {
  color: var(--text-error);
}

/* 4x5 Button Grid wrapper */
.button-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px; /* grid-gap */
}

/* Standard Tactical interactive button element */
.calc-button {
  aspect-ratio: 1; /* Squarish desktop ratio */
  min-height: 48px; /* Interactive mobile tap target clearance min */
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  font-size: 20px;
  font-weight: 600;
  border-radius: 8px; /* rounded-button */
  border: var(--border-btn);
  box-shadow: var(--shadow-btn);
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition: transform 0.1s ease-in-out, background-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
  outline: none;
}

/* Active plunge transforms simulating physical plunger button travel */
.calc-button:active:not(:disabled) {
  transform: scale(0.97);
  box-shadow: none;
}

.calc-button:focus-visible {
  box-shadow: 0px 0px 0px 3px var(--btn-focus-ring);
}

.calc-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Hierarchy Color Styles mapped from DESIGN.md */
.calc-button.operand {
  background-color: var(--btn-operand-bg);
  color: var(--btn-operand-text);
}

.calc-button.operand:hover:not(:disabled) {
  background-color: var(--bg-app);
  box-shadow: var(--shadow-btn-hover);
}

.calc-button.operator {
  background-color: var(--btn-operator-bg);
  color: var(--btn-operator-text);
}

.calc-button.operator:hover:not(:disabled) {
  filter: brightness(0.95);
  box-shadow: var(--shadow-btn-hover);
}

.calc-button.command {
  background-color: var(--btn-command-bg);
  color: var(--btn-command-text);
}

.calc-button.command:hover:not(:disabled) {
  filter: brightness(0.92);
  box-shadow: var(--shadow-btn-hover);
}

.calc-button.equals {
  background-color: var(--btn-equals-bg);
  color: var(--btn-equals-text);
}

.calc-button.equals:hover:not(:disabled) {
  filter: brightness(1.1);
  box-shadow: var(--shadow-btn-hover);
}

